import pathlib,hashlib,json
root=pathlib.Path('products/sites/shopify-catalogue-example')
evidence=[]
for prefix in ['products/reviews','products/distribution']:
 for p in pathlib.Path(prefix).rglob('*'):
  if p.is_file() and p.suffix in ['.json','.md']:
   evidence.append((str(p),p.read_text(errors='replace')))
rows=[]
for p in sorted(root.rglob('*')):
 if p.is_file() and p.name!='index.html':
  h=hashlib.sha256(p.read_bytes()).hexdigest()
  matches=[name for name,text in evidence if h in text]
  rows.append({'path':str(p),'sha256':h,'historical_evidence_candidates':matches,'interpretation':'Citation requires inspection; hash occurrence alone is not independent approval.'})
result={'remaining_inventory':rows,'scope':'Evidence lookup only. No runtime tests, public edits, deployment, demand or revenue established.'}
out=pathlib.Path('products/services/catalogue-qa/evidence-to-offer/historical-hash-lookup.json');out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(result,indent=2));print(out.read_text())
